public class AdvancedClicker { public static void main(String[] args) { javax.swing.JFrame f = new javax.swing.JFrame("Ultimate Diamond Clicker"); java.util.concurrent.atomic.AtomicLong d = new java.util.concurrent.atomic.AtomicLong(0), c = new java.util.concurrent.atomic.AtomicLong(1), p = new java.util.concurrent.atomic.AtomicLong(0); javax.swing.JLabel l = new javax.swing.JLabel("Diamonds: 0  (+1/c, +0/s)", 0); l.setFont(new java.awt.Font("Arial", 1, 18)); l.setForeground(java.awt.Color.WHITE); javax.swing.JPanel m = new javax.swing.JPanel(new java.awt.GridLayout(0, 1, 5, 5)); m.setBackground(new java.awt.Color(30, 30, 40)); java.util.function.Runnable u = () -> l.setText(String.format("Diamonds: %d  (+%d/c, +%d/s)", d.get(), c.get(), p.get())); javax.swing.JButton b = new javax.swing.JButton() { @Override protected void paintComponent(java.awt.Graphics g) { super.paintComponent(g); java.awt.Graphics2D g2 = (java.awt.Graphics2D) g; g2.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING, java.awt.RenderingHints.VALUE_ANTIALIAS_ON); int w = getWidth(), h = getHeight(), cx = w / 2, cy = h / 2, r = Math.min(w, h) / 3; int[][] pts = {{cx, cy - r}, {cx + r, cy}, {cx, cy + r}, {cx - r, cy}, {cx, cy - r / 3}, {cx, cy + r / 3}, {cx - r / 2, cy}, {cx + r / 2, cy}}; int[][] faces = {{0, 7, 4}, {0, 4, 6}, {0, 6, 3}, {0, 1, 7}, {2, 7, 5}, {2, 5, 6}, {2, 6, 3}, {2, 1, 7}, {4, 7, 5}, {4, 5, 6}}; java.awt.Color[] shades = {new java.awt.Color(220, 245, 255), new java.awt.Color(180, 230, 255), new java.awt.Color(140, 210, 255), new java.awt.Color(200, 240, 255), new java.awt.Color(100, 180, 240), new java.awt.Color(80, 160, 230), new java.awt.Color(60, 140, 210), new java.awt.Color(160, 220, 255), new java.awt.Color(120, 200, 255), new java.awt.Color(90, 170, 235)}; for (int i = 0; i < faces.length; i++) { java.awt.Polygon poly = new java.awt.Polygon(); for (int j = 0; j < 3; j++) poly.addPoint(pts[faces[i][j]][0], pts[faces[i][j]][1]); g2.setColor(shades[i % shades.length]); g2.fill(poly); g2.setColor(new java.awt.Color(255, 255, 255, 100)); g2.draw(poly); } } }; b.setContentAreaFilled(false); b.setBorderPainted(false); b.setFocusPainted(false); b.addActionListener(e -> { d.addAndGet(c.get()); u.run(); }); for (int i = 1; i <= 20; i++) { final int id = i; java.util.concurrent.atomic.AtomicLong cost = new java.util.concurrent.atomic.AtomicLong(id * 15); javax.swing.JButton ub = new javax.swing.JButton("Upgrade " + id + " (Cost: " + cost.get() + ")"); ub.setFont(new java.awt.Font("Arial", 0, 12)); ub.addActionListener(e -> { if (d.get() >= cost.get()) { d.addAndGet(-cost.get()); if (id % 2 == 1) c.addAndGet(id); else p.addAndGet(id * 2); cost.set((long) (cost.get() * 1.5)); ub.setText((id % 2 == 1 ? "Click Power +" : "Passive Overdrive +") + id + " (Cost: " + cost.get() + ")"); u.run(); } }); m.add(ub); } new javax.swing.Timer(1000, e -> { d.addAndGet(p.get()); u.run(); }).start(); javax.swing.JPanel pnl = new javax.swing.JPanel(new java.awt.BorderLayout(10, 10)); pnl.setBackground(new java.awt.Color(20, 20, 25)); pnl.setBorder(javax.swing.BorderFactory.createEmptyBorder(15, 15, 15, 15)); pnl.add(l, "North"); pnl.add(b, "Center"); pnl.add(new javax.swing.JScrollPane(m) {{ getVerticalScrollBar().setUnitIncrement(16); setPreferredSize(new java.awt.Dimension(280, 0)); }}, "East"); f.setContentPane(pnl); f.setSize(850, 550); f.setDefaultCloseOperation(3); f.setLocationRelativeTo(null); f.setVisible(true); } }
